                state.decisions = {
                    primary: 'rf1',
                    secondary: 'normal',
                    intensity: 5,
                    communication: 'controlled'
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 0);
        }

        validateDecisions(decisions) {
            var p = document.getElementById('primaryChoice');
            var s = document.getElementById('secondaryChoice');
            var i = document.getElementById('intensityInput');
            var c = document.getElementById('communicationChoice');

            if (p) decisions.primary = p.value;
            if (s) decisions.secondary = s.value;
            if (i) decisions.intensity = parseInt(i.value, 10);
            if (c) decisions.communication = c.value;

            if (!decisions.primary || !decisions.secondary) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.intensity || decisions.intensity < 1 || decisions.intensity > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('intensity_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var round = state.currentPeriod;

            var repDelta = 0;
            var exposureDelta = 0;
            var cashDelta = 0;
            var clientsDelta = 0;
            var diagnosisCorrect = false;
            var feedbackKey = 'fb_generic';

            if (round === 1) {
                var expected = CORRECT_R1[d.primary];
                if (expected && expected === d.secondary) {
                    diagnosisCorrect = true;
                    repDelta += 12;
                    exposureDelta += 4500;
                    feedbackKey = 'fb_r1_correct';
                } else {
                    repDelta -= 8;
                    exposureDelta += 500;
                    cashDelta -= 200;
                    clientsDelta -= 1;
                    feedbackKey = 'fb_r1_wrong';
                }
                if (d.intensity >= 5 && d.intensity <= 7) { repDelta += 3; cashDelta -= 80; }
                else if (d.intensity < 3) { repDelta -= 5; cashDelta -= 30; }
                else if (d.intensity > 8) { cashDelta -= 180; repDelta += 1; }

                if (d.communication === 'controlled') repDelta += 4;
                else if (d.communication === 'proactive') { repDelta += 2; cashDelta -= 120; }
                else if (d.communication === 'internal') { repDelta -= 3; clientsDelta -= 0; }

            } else if (round === 2) {
                if (d.primary === 'rebuild') { repDelta += 10; exposureDelta += 5000; cashDelta -= 420; }
                else if (d.primary === 'outsource') { repDelta += 5; exposureDelta += 3500; cashDelta -= 720; }
                else if (d.primary === 'patch') { repDelta -= 4; exposureDelta += 1200; cashDelta -= 120; clientsDelta -= 1; }
                else if (d.primary === 'defer') { repDelta -= 14; exposureDelta += 0; cashDelta -= 60; clientsDelta -= 3; }

                if (d.secondary === 'full_battery') { repDelta += 8; exposureDelta += 2500; cashDelta -= 220; }
                else if (d.secondary === 'ks_ad') { repDelta += 4; exposureDelta += 1500; cashDelta -= 110; }
                else if (d.secondary === 'qq_only') { repDelta += 0; exposureDelta += 500; cashDelta -= 50; }
                else if (d.secondary === 'none') { repDelta -= 15; clientsDelta -= 2; }

                if (d.intensity >= 6 && d.intensity <= 8) { repDelta += 3; cashDelta -= 300; }
                else if (d.intensity <= 3) { repDelta -= 5; cashDelta -= 100; }
                else if (d.intensity >= 9) { cashDelta -= 600; repDelta += 1; }

                if (d.communication === 'proactive') repDelta += 6;
                else if (d.communication === 'controlled') repDelta += 2;
                else if (d.communication === 'internal') { repDelta -= 5; clientsDelta -= 1; }

                feedbackKey = (d.primary === 'rebuild' && d.secondary === 'full_battery') ? 'fb_r2_best' : 'fb_r2_generic';

            } else if (round === 3) {
                if (d.primary === 'triage_top3') { repDelta += 10; exposureDelta += 5500; cashDelta -= 150; }
                else if (d.primary === 'parallel_all') { repDelta += 2; exposureDelta += 3000; cashDelta -= 400; }
                else if (d.primary === 'serial') { repDelta -= 3; exposureDelta += 1800; clientsDelta -= 2; cashDelta -= 100; }
                else if (d.primary === 'abandon_low') { repDelta -= 8; exposureDelta += 2000; clientsDelta -= 3; cashDelta += 100; }

                if (d.secondary === 'senior_limited') { repDelta += 6; exposureDelta += 1500; cashDelta -= 250; }
                else if (d.secondary === 'aggressive') { repDelta += 2; exposureDelta += 2500; cashDelta -= 700; }
                else if (d.secondary === 'no_contractors') { repDelta -= 4; exposureDelta += 800; clientsDelta -= 1; }
                else if (d.secondary === 'contractor_only') { repDelta -= 6; exposureDelta += 1000; cashDelta -= 900; clientsDelta -= 1; }

                if (d.intensity >= 8) { repDelta += 5; exposureDelta += 1200; cashDelta -= 280; }
                else if (d.intensity >= 5) { repDelta += 1; exposureDelta += 400; cashDelta -= 140; }
                else { repDelta -= 6; clientsDelta -= 1; cashDelta -= 40; }

                if (d.communication === 'proactive') repDelta += 5;
                else if (d.communication === 'controlled') repDelta += 2;
                else if (d.communication === 'internal') { repDelta -= 6; clientsDelta -= 2; }

                feedbackKey = (d.primary === 'triage_top3' && d.secondary === 'senior_limited') ? 'fb_r3_best' : 'fb_r3_generic';

            } else if (round === 4) {
                if (d.primary === 'comprehensive') { repDelta += 14; exposureDelta += 4500; cashDelta -= 500; }
                else if (d.primary === 'validation_std') { repDelta += 8; exposureDelta += 2800; cashDelta -= 250; }
                else if (d.primary === 'external_audit') { repDelta += 6; exposureDelta += 2200; cashDelta -= 900; }
                else if (d.primary === 'checklist') { repDelta += 2; exposureDelta += 800; cashDelta -= 60; }

                if (d.secondary === 'model_committee') { repDelta += 8; exposureDelta += 2000; cashDelta -= 200; }
                else if (d.secondary === 'board_oversight') { repDelta += 5; exposureDelta += 1500; cashDelta -= 300; }
                else if (d.secondary === 'peer_review') { repDelta += 4; exposureDelta += 1000; cashDelta -= 80; }
                else if (d.secondary === 'no_change') { repDelta -= 10; exposureDelta -= 400; clientsDelta -= 2; }

                if (d.intensity >= 6 && d.intensity <= 8) { repDelta += 4; cashDelta -= 210; }
                else if (d.intensity <= 3) { repDelta -= 4; cashDelta -= 40; }
                else if (d.intensity >= 9) { cashDelta -= 480; repDelta += 1; }

                if (d.communication === 'proactive') repDelta += 6;
                else if (d.communication === 'controlled') repDelta += 2;
                else if (d.communication === 'internal') { repDelta -= 4; }

                feedbackKey = (d.primary === 'comprehensive' && d.secondary === 'model_committee') ? 'fb_r4_best' : 'fb_r4_generic';
            }

            state.domainState.reputation = Math.max(0, Math.min(100, state.domainState.reputation + repDelta));
            state.domainState.exposureMitigated = Math.max(0, Math.min(TOTAL_EXPOSURE, state.domainState.exposureMitigated + exposureDelta));
            state.domainState.cash = state.domainState.cash + cashDelta;
            state.domainState.clientsRetained = Math.max(0, Math.min(23, state.domainState.clientsRetained + clientsDelta));
            if (diagnosisCorrect) state.domainState.correctDiagnoses++;

            state.domainState.reputationHistory.push(state.domainState.reputation);
            state.domainState.exposureHistory.push(state.domainState.exposureMitigated);
            state.domainState.cashHistory.push(state.domainState.cash);
            state.domainState.clientsHistory.push(state.domainState.clientsRetained);

            // platform score: composite of the same three fields getPerformanceSummary gates its verdict tiers on
            // (reputation is already 0-100, exposure mitigated and clients retained are scaled to 0-100 by their own caps),
            // weighted like the tiers, where reputation and exposure gate every tier and clients only the top two
            var pfRep = state.domainState.reputation;
            var pfExp = Math.min(100, Math.round(100 * state.domainState.exposureMitigated / TOTAL_EXPOSURE));
            var pfClients = Math.min(100, Math.round(100 * state.domainState.clientsRetained / 23));
            var pfScore = Math.round(pfRep * 0.4 + pfExp * 0.4 + pfClients * 0.2);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, pfScore)) });

            // The framework advances currentPeriod AFTER calculateResults; the briefing is
            // primarily driven by the 'period:submitted' event (see _wireFrameworkEvents).
            // This guarded timer is a portable fallback that renders the live (already
            // advanced) round WITHOUT adding +1, and only if the event has not already done so.
            var self = this;
            setTimeout(function() {
                if (!window.mySimulation || !window.mySimulation.state) return;
                var live = window.mySimulation.state.currentPeriod;
                if (typeof live === 'number' && live > self._lastRenderedPeriod && live <= MAX_ROUNDS) {
                    self._updateBriefing(window.mySimulation.state);
                }
            }, 300);

            return {
                period: state.currentPeriod,
                primary: d.primary,
                secondary: d.secondary,
                intensity: d.intensity,
                communication: d.communication,
                repDelta: repDelta,
                exposureDelta: exposureDelta,
                cashDelta: cashDelta,
                clientsDelta: clientsDelta,
                reputation: state.domainState.reputation,
                exposureMitigated: state.domainState.exposureMitigated,
                cash: state.domainState.cash,
                clientsRetained: state.domainState.clientsRetained,
                diagnosisCorrect: diagnosisCorrect,
                feedbackKey: feedbackKey
            };
        }

