        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1].results || {};
            var finalRep = last.reputation != null ? last.reputation : 0;
            var finalExp = last.exposureMitigated != null ? last.exposureMitigated : 0;
            var finalClients = last.clientsRetained != null ? last.clientsRetained : 0;
            var finalCash = last.cash != null ? last.cash : 0;
            var totalCorrect = history.reduce(function(s, r) { return s + ((r.results && r.results.diagnosisCorrect) ? 1 : 0); }, 0);

            var perfKey = 'perf_beginner';
            if (finalRep >= 80 && finalExp >= 15000 && finalClients >= 20) perfKey = 'perf_excellent';
            else if (finalRep >= 65 && finalExp >= 10000 && finalClients >= 18) perfKey = 'perf_good';
            else if (finalRep >= 50 && finalExp >= 6000) perfKey = 'perf_adequate';
            var tt = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var performance = tt(perfKey);

            var insights = [];
            if (finalRep < 50) insights.push(window.mySimulation.t('ins_low_rep'));
            if (finalExp < 8000) insights.push(window.mySimulation.t('ins_low_exp'));
            if (finalClients < 20) insights.push(window.mySimulation.t('ins_lost_clients'));
            if (finalRep >= 80 && finalExp >= 15000) insights.push(window.mySimulation.t('ins_strong_turnaround'));
            if (!insights.length) insights.push(window.mySimulation.t('ins_balanced'));

            return {
                totalExposureMitigated: finalExp,
                totalExposure: TOTAL_EXPOSURE,
                finalReputation: finalRep,
                finalClients: finalClients,
                finalCash: finalCash,
                correctDiagnoses: totalCorrect,
                performance: performance,
                performanceKey: perfKey,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.feedbackKey === 'fb_r1_wrong') return window.mySimulation.t('hint_r1_wrong');
            if (results.clientsDelta < 0) return window.mySimulation.t('hint_lost_client');
            if (results.repDelta < 0) return window.mySimulation.t('hint_reputation_drop');
            if (state.domainState.reputation < 50) return window.mySimulation.t('hint_low_rep');
            if (state.domainState.exposureMitigated > 15000) return window.mySimulation.t('hint_strong_progress');
            if (results.feedbackKey) return window.mySimulation.t(results.feedbackKey);
            return null;
        }

