        _labelFor(kind, value) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(x) { return x; };
            for (var round in ROUND_CONFIG) {
                var list = kind === 'primary' ? ROUND_CONFIG[round].primaryOptions : ROUND_CONFIG[round].secondaryOptions;
                for (var j = 0; j < list.length; j++) {
                    if (list[j].v === value) return t(list[j].k);
                }
            }
            return value;
        }

