        _wireFrameworkEvents() {
            if (this._wired) return;
            var sim = window.mySimulation;
            if (!sim || !sim.eventBus) return;
            var self = this;
            sim.eventBus.on('period:submitted', function() { self._onPeriodSubmitted(); });
            sim.eventBus.on('period:undone', function() { self._onPeriodUndone(); });
            document.addEventListener('express:langchanged', function() {
                try {
                    self._lastRenderedPeriod = 0;
                    self._updateBriefing(window.mySimulation.state);
                    self._renderHint();
                } catch (e) {}
            });
            this._wired = true;
        }

        _onPeriodSubmitted() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var live = sim.state.currentPeriod;
            // The framework advances currentPeriod AFTER grading. Render the NEW round
            // (briefing, labels, options) for the live period, guarded so we never render
            // past the final round or re-render a round we already drew.
            if (typeof live === 'number' && live > this._lastRenderedPeriod && live <= MAX_ROUNDS) {
                this._updateBriefing(sim.state);
            }
            this._renderHint();
        }

        _onPeriodUndone() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            // Undoing the first round empties history; the framework's initialize() guard
            // will NOT reset a non-empty domainState, so reset it here to keep the KPI
            // displays consistent with an empty history.
            if (!sim.state.history || sim.state.history.length === 0) {
                sim.state.domainState = this._defaultDomainState();
                try { sim.updateUI(); } catch (e) {}
            }
            this._lastRenderedPeriod = 0;
            this._updateBriefing(sim.state);
            this._clearHint();
        }

        _renderHint() {
            var box = document.getElementById('hintBox');
            if (!box) return;
            var sim = window.mySimulation;
            var results = (sim && sim.state) ? sim.state.results : null;
            var hint = null;
            try { hint = this.getHint(sim.state, results); } catch (e) { hint = null; }
            box.textContent = hint || '';
        }

        _clearHint() {
            var box = document.getElementById('hintBox');
            if (box) box.textContent = '';
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var s = summary || {};
            var rep = (s.finalReputation != null ? Math.round(s.finalReputation) : 0);
            var exp = (s.totalExposureMitigated != null ? s.totalExposureMitigated : 0);
            var total = (s.totalExposure != null ? s.totalExposure : TOTAL_EXPOSURE);
            var pct = total > 0 ? Math.round((exp / total) * 100) : 0;
            var clients = (s.finalClients != null ? s.finalClients : 0);
            var correct = (s.correctDiagnoses != null ? s.correctDiagnoses : 0);
            var cash = (s.finalCash != null ? Math.round(s.finalCash) : 0);
            var perf = s.performance || '';
            var insight = (s.insights && s.insights.length) ? s.insights[0] : '';
            var fmtCop = function(v) { return 'COP ' + Number(v).toLocaleString() + 'M'; };
            var row = function(label, value) {
                return '<div style="display:flex;justify-content:space-between;gap:16px;padding:7px 2px;border-bottom:1px solid #e5e9f0;">' +
                    '<span style="color:#6b7280;">' + label + '</span>' +
                    '<span style="font-weight:700;color:#0b7a4b;">' + value + '</span></div>';
            };
            return '<div style="padding:8px 4px;text-align:left;max-width:440px;margin:0 auto;">' +
                '<h4 style="text-align:center;color:#0b7a4b;margin:0 0 16px;">' + t('summary_title') + '</h4>' +
                row(t('summary_performance'), '<b>' + perf + '</b>') +
                row(t('summary_reputation'), rep + ' / 100') +
                row(t('summary_exposure'), fmtCop(exp) + ' (' + pct + '%)') +
                row(t('summary_clients'), clients + ' / 23') +
                row(t('summary_correct'), String(correct)) +
                row(t('summary_cash'), fmtCop(cash)) +
                '<p style="margin:16px 0 0;line-height:1.55;color:#333;">' + insight + '</p>' +
                '</div>';
        }

